class CamelCaseMap:
    def __init__(self):
        self._data = {}

    def __getitem__(self, key):
        return self._get_data(self._convert_key(key))

    def __setitem__(self, key, value):
        self._set_data(self._convert_key(key), value)

    def __delitem__(self, key):
        self._delete_data(self._convert_key(key))

    def __iter__(self):
        return iter(self._get_all_data())

    def __len__(self):
        return self._data_size()

    def _convert_key(self, key):
        if not isinstance(key, str):
            return key
        return self._to_camel_case(key)

    @staticmethod
    def _to_camel_case(key):
        parts = key.split('_')
        first_part = parts[0]
        remaining_parts = parts[1:]
        capitalized_remaining = ''.join(part.title() for part in remaining_parts)
        return first_part + capitalized_remaining

    def _get_data(self, key):
        return self._data[key]

    def _set_data(self, key, value):
        self._data[key] = value

    def _delete_data(self, key):
        del self._data[key]

    def _get_all_data(self):
        return self._data

    def _data_size(self):
        return len(self._data)
